// src/contentFactory.js
export function contentFactory(mode, token) {
  return async (data) => {
    const formData = new FormData();

    // Основні поля
    formData.append("title", data.title);
    formData.append("content", data.content);
    formData.append("excerpt", data.excerpt || "");
    formData.append("is_premium", data.is_premium ? "true" : "false");
    formData.append("type", data.type);
    formData.append("subtype", data.subtype || "standard");

    // Якщо це звичайна стаття
    if (data.type === "standard") {
      formData.append("category", data.category);
    }

    // Якщо це стаття для каналу
    if (data.type === "channel" && data.channel) {
      formData.append("channel", data.channel);
    }

    // Фото (якщо subtype дозволяє)
    if (data.image && data.subtype === "standard") {
      formData.append("image", data.image);
    }

    const res = await fetch("http://127.0.0.1:8000/api/articles/", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
      },
      body: formData,
    });

    if (!res.ok) {
      const err = await res.text();
      throw new Error(`Помилка створення: ${err}`);
    }

    return await res.json();
  };
}
